$orgId=(int)($_GET['organization_id'] ?? $_POST['organization_id'] ?? 0); $departments=[]; if($orgId){$ds=db()->prepare("SELECT id,name FROM departments WHERE organization_id=? AND status='active' ORDER BY name");$ds->execute([$orgId]);$departments=$ds->fetchAll();}
$errors=[]; $visitType=(string)($_POST['visit_type']??'general_checkup'); $reason=trim((string)($_POST['reason']??'')); $startsAt=(string)($_POST['starts_at']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $orgId=(int)($_POST['organization_id']??0); $departmentId=(int)($_POST['department_id']??0); $visitType=(string)($_POST['visit_type']??'general_checkup'); $reason=trim((string)($_POST['reason']??'')); $startsAt=(string)($_POST['starts_at']??'');
 $orgCheck=db()->prepare("SELECT id,name FROM organizations WHERE id=? AND approval_status='approved'");$orgCheck->execute([$orgId]);$org=$orgCheck->fetch();
 if(!$org)$errors[]='Choose an approved hospital or clinic.';
 if(!in_array($visitType,['general_checkup','condition_specific','follow_up','vaccination','other'],true))$errors[]='Choose a valid visit type.';
 if($visitType==='condition_specific' && mb_strlen($reason)<2)$errors[]='Enter the condition or symptoms you want the appointment for.';
 $dt=DateTime::createFromFormat('Y-m-d\\TH:i',$startsAt); if(!$dt || $dt<=new DateTime())$errors[]='Choose a future appointment date and time.';
 if($departmentId){$d=db()->prepare("SELECT id FROM departments WHERE id=? AND organization_id=? AND status='active'");$d->execute([$departmentId,$orgId]);if(!$d->fetch())$errors[]='Choose a valid department for the selected provider.';}
 if(!$errors){$label=match($visitType){'general_checkup'=>'General check-up','condition_specific'=>'Condition-specific: '.$reason,'follow_up'=>'Follow-up visit','vaccination'=>'Vaccination','other'=>'Other: '.$reason};$stmt=db()->prepare("INSERT INTO appointments (organization_id,patient_user_id,department_id,starts_at,reason,status) VALUES (?,?,?,?,?,'requested')");$stmt->execute([$orgId,$user['id'],$departmentId?:null,$dt->format('Y-m-d H:i:s'),$label]);$ticket=(int)db()->lastInsertId();$owner=db()->prepare('SELECT u.email,u.full_name FROM organizations o JOIN users u ON u.id=o.owner_user_id WHERE o.id=?');$owner->execute([$orgId]);$hospitalOwner=$owner->fetch();if($hospitalOwner)send_carebridge_email($hospitalOwner['email'],'New appointment request — CareBridge','A new appointment request has arrived','Hello '.$hospitalOwner['full_name'].', a patient has requested an appointment. Please sign in to your provider workspace to review and update the queue ticket.',['Ticket ID'=>'CB-T'.str_pad((string)$ticket,6,'0',STR_PAD_LEFT),'Organization'=>$org['name'],'Requested for'=>$dt->format('M j, Y g:i A')]);send_carebridge_email($user['email'],'Appointment request received','Your appointment request has been recorded','Your request has been sent to '.$org['name'].'. The hospital will review it and update the ticket status.',['Ticket ID'=>'CB-T'.str_pad((string)$ticket,6,'0',STR_PAD_LEFT),'Provider'=>$org['name'],'Requested for'=>$dt->format('M j, Y g:i A'),'Status'=>'Requested']);flash('success','Appointment request submitted. Your ticket is CB-T'.str_pad((string)$ticket,6,'0',STR_PAD_LEFT).'.');redirect('dashboard.php');}
 if($orgId){$ds=db()->prepare("SELECT id,name FROM departments WHERE organization_id=? AND status='active' ORDER BY name");$ds->execute([$orgId]);$departments=$ds->fetchAll();}
}
